31	async function refresh() {
32	  const s = await send('getStatus');
33	  const cfg = (s && s.config) || {};
34	  const stores = (s && s.stores) || {};
35	
36	  document.getElementById('cfg').textContent =
37	    '飞书：' + (cfg.webhook ? (cfg.enabled ? '已启用' : '已停用') : '未配置')
38	    + '　后台：' + (s && s.bgVersion ? s.bgVersion : '旧版·需强制刷新');
39	
40	  const lc = s && s.lastCycle;
41	  const mr = s && s.lastMustRemind;
42	  const ci = document.getElementById('cycleInfo');
43	  const parts = [];
44	  let bad = false;
45	  if (lc && lc.ts) {
46	    const failed = /失败|没找到|打不开/.test(lc.summary || '');
47	    if (failed) bad = true;
48	    parts.push('上次轮巡：' + fmtTs(lc.ts) + (failed ? '（有异常，点轮巡重试）' : ''));
49	  }
50	  if (mr && mr.ts) {
51	    if (mr.ok === false) bad = true;
52	    parts.push('上次必提醒：' + fmtTs(mr.ts) + (mr.ok === false ? '（发送失败）' : ''));
53	  }
54	  const times = cfg.mustRemindEnabled === false
55	    ? '已关'
