57	      ? cfg.mustRemindTimes.join('/')
58	      : '09:30/16:30');
59	  parts.push('必提醒：' + times);
60	  ci.textContent = parts.join(' · ');
61	  ci.className = bad ? 'sub err' : 'sub';
62	
63	  const names = Object.keys(stores).sort();
64	  const box = document.getElementById('stores');
65	  if (names.length === 0) {
66	    box.innerHTML = '<div class="empty">还没有数据。切到某个店的商品列表页（并点“立即检查”）即可开始监测该店。</div>';
67	    return;
68	  }
69	  box.innerHTML = names.map((name) => {
70	    const L = (stores[name] && stores[name].latest) || {};
71	    return `<div class="store">
72	      <div class="name"><span>🏬 ${esc(name)}</span><span class="r"><span class="t">${fmtTs(L.ts)}</span><span class="del" data-name="${esc(name)}" title="删除该店">✕</span></span></div>
73	      <div class="kv">
74	        <span>在售 <b>${num(L.onSale)}</b></span>
75	        <span>流量待关注 <b>${num(L.trafficWatch)}</b></span>
76	        <span>流量下降 <b style="${typeof L.trafficDecline === 'number' && L.trafficDecline > 0 ? 'color:#d92d20' : ''}">${typeof L.trafficDecline === 'number' ? L.trafficDecline : '—'}</b></span>
77	        <span>总数 ${num(L.total)}</span>
78	        <span>未发布/已下架 ${num(L.unpublished)}/${num(L.removed)}</span>
79	      </div>
80	      ${itemsHtml(L.watchItems, '限流商品：', '#d97706')}
81	      ${itemsHtml(L.declineItems, '流量下降：', '#d92d20')}
82	      ${skuSpecsHtml(L.skuSpecs)}
83	    </div>`;
84	  }).join('');
85	  box.querySelectorAll('.del').forEach((el) => {
86	    el.addEventListener('click', async () => {
87	      const name = el.getAttribute('data-name');
88	      if (!confirm('确定删除「' + name + '」的监测数据？')) return;
89	      const r = await send('deleteStore', { name });
90	      setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
