99	  if (!name) { setMsg('请输入店铺名', 'err'); return; }
100	  const r = await send('addStore', { name });
101	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
102	  if (r && r.ok) { input.value = ''; refresh(); }
103	}
104	
105	document.getElementById('add').addEventListener('click', addStore);
106	document.getElementById('newStore').addEventListener('keydown', (e) => { if (e.key === 'Enter') addStore(); });
107	
108	document.getElementById('cycle').addEventListener('click', async () => {
109	  setMsg('正在轮巡所有店（会切店，约 1-2 分钟，请勿操作页面）…');
110	  const r = await send('cycleNow');
111	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
112	  setTimeout(refresh, 1500);
113	});
114	document.getElementById('check').addEventListener('click', async () => {
115	  setMsg('正在刷新后台页…');
116	  const r = await send('checkNow');
117	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
118	  setTimeout(refresh, 4000);
119	});
120	document.getElementById('test').addEventListener('click', async () => {
121	  setMsg('正在发送测试…');
122	  const r = await send('testFeishu');
123	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
124	});
125	document.getElementById('opt').addEventListener('click', (e) => {
126	  e.preventDefault();
127	  chrome.runtime.openOptionsPage();
128	});
129	
130	refresh();
