132	// ---- Log viewer ----
133	var logVisible = false;
134	var logTimer = null;
135	
136	function fetchAndRenderLogs() {
137	  chrome.storage.local.get('logs', function (r) {
138	    var logs = r.logs || [];
139	    var recent = logs.slice(-100).reverse();
140	    var listEl = document.getElementById('logList');
141	    var countEl = document.getElementById('logCount');
142	    countEl.textContent = logs.length + ' 条';
143	
144	    var html = '';
145	    for (var i = 0; i < recent.length; i++) {
146	      var e = recent[i];
147	      var color = '#1f2329';
148	      if (e.level === 'WARN')  color = '#d97706';
149	      if (e.level === 'ERROR') color = '#d92d20';
150	      html += '<div style="color:' + color + '">[' + esc(e.ts) + '] [' + esc(e.level) + '] ' + esc(e.msg) + '</div>';
151	    }
152	    if (!recent.length) {
153	      html = '<div style="color:#8a9099">（暂无日志）</div>';
154	    }
155	    listEl.innerHTML = html;
156	    if (logVisible) listEl.scrollTop = 0;
157	  });
158	}
159	
160	function toggleLogs() {
161	  logVisible = !logVisible;
162	  var listEl = document.getElementById('logList');
163	  var exportBtn = document.getElementById('logExport');
164	  var toggleBtn = document.getElementById('logToggle');
165	
166	  if (logVisible) {
167	    listEl.style.display = 'block';
168	    exportBtn.style.display = '';
169	    toggleBtn.textContent = '📋 隐藏日志';
170	    fetchAndRenderLogs();
171	    logTimer = setInterval(fetchAndRenderLogs, 3000);
172	  } else {
173	    listEl.style.display = 'none';
174	    exportBtn.style.display = 'none';
175	    toggleBtn.textContent = '📋 日志';
176	    if (logTimer) { clearInterval(logTimer); logTimer = null; }
177	  }
178	}
179	
180	function exportLogs() {
181	  chrome.storage.local.get('logs', function (r) {
182	    var logs = r.logs || [];
183	    var text = '';
184	    for (var i = 0; i < logs.length; i++) {
185	      text += '[' + logs[i].ts + '] [' + logs[i].level + '] ' + logs[i].msg + '\n';
186	    }
187	    if (!text) text = '(no logs)\n';
188	    var blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
189	    var url = URL.createObjectURL(blob);
190	    var a = document.createElement('a');
191	    a.href = url;
192	    a.download = 'temu-monitor-' + new Date().toISOString().slice(0, 10) + '.log';
193	    a.click();
