86	// ---------------- 飞书 ----------------
87	// template：飞书卡片色条 red/orange/blue/green/turquoise/wathet/purple/violet/carmine/yellow/grey
88	async function sendFeishu(webhook, title, lines, template) {
89	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
90	  const card = {
91	    msg_type: 'interactive',
92	    card: {
93	      header: { title: { tag: 'plain_text', content: title }, template: template || 'red' },
94	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
