98	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
99	    const data = await resp.json().catch(() => ({}));
100	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
101	    if (ok) log.info('Feishu sent OK: ' + title);
102	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
103	  } catch (e) {
