109	// ---------------- 定时必提醒（每天固定时刻强制汇报各店状态） ----------------
110	function parseHHMM(s) {
111	  const m = String(s || '').trim().match(/^(\d{1,2})[:.：](\d{2})$/);
112	  if (!m) return null;
113	  const h = Number(m[1]);
114	  const min = Number(m[2]);
115	  if (h > 23 || min > 59) return null;
116	  return { h, min, label: String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0') };
117	}
118	// 下一次触发时间戳（本地时区）；若今天该时刻已过（或 5 秒内），排到明天
119	function nextWhen(hhmm) {
120	  const p = parseHHMM(hhmm);
121	  if (!p) return null;
122	  const now = new Date();
123	  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), p.h, p.min, 0, 0);
124	  if (t.getTime() <= now.getTime() + 5000) t.setDate(t.getDate() + 1);
125	  return t.getTime();
126	}
127	function fmtNum(v) { return typeof v === 'number' ? String(v) : '—'; }
128	async function sendMustRemind(slot) {
129	  const cfg = await getConfig();
130	  if (!cfg.enabled || cfg.mustRemindEnabled === false) {
131	    log.info('MustRemind skipped: disabled');
132	    return { ok: false, msg: '未启用' };
133	  }
134	  if (!cfg.webhook) {
135	    log.warn('MustRemind skipped: no webhook');
136	    return { ok: false, msg: '未配置飞书 webhook' };
137	  }
138	  const stores = await getStores();
139	  const names = Object.keys(stores).sort();
140	  const lines = [
141	    '**定时必提醒' + (slot ? ' · ' + slot : '') + '**',
142	    '_插件存活汇报（无异常也会发）_',
143	    '',
144	  ];
145	  if (!names.length) {
146	    lines.push('_暂无店铺数据。请打开 goods/list 或点「轮巡所有店」。_');
147	  } else {
148	    for (const name of names) {
149	      const L = (stores[name] && stores[name].latest) || {};
150	      const stale = L.ts && (Date.now() - L.ts > 2 * 60 * 60 * 1000);
151	      lines.push('**🏬 ' + name + '**' + (stale ? ' ⚠️数据超过2小时未更新' : ''));
152	      lines.push(
153	        '在售 **' + fmtNum(L.onSale) + '**'
154	        + ' · 待关注 **' + fmtNum(L.trafficWatch) + '**'
155	        + ' · 下降 **' + fmtNum(L.trafficDecline) + '**'
156	        + ' · 总数 ' + fmtNum(L.total)
157	      );
158	      lines.push('上次检查：' + (L.ts ? new Date(L.ts).toLocaleString('zh-CN') : '—'));
159	      lines.push('');
160	    }
161	  }
162	  const lastCycle = (await chrome.storage.local.get('lastCycle')).lastCycle;
163	  if (lastCycle && lastCycle.ts) {
164	    lines.push('上次轮巡：' + new Date(lastCycle.ts).toLocaleString('zh-CN'));
165	  }
166	  lines.push('_汇报时间：' + new Date().toLocaleString('zh-CN') + '_');
167	  const r = await sendFeishu(cfg.webhook, '📋 Temu 监测定时汇报', lines, 'blue');
168	  await chrome.storage.local.set({ lastMustRemind: { ts: Date.now(), ok: r.ok, msg: r.msg, slot: slot || '' } });
169	  log.info('MustRemind done: slot=' + (slot || '') + ' ok=' + r.ok);
170	  return r;
171	}
172	async function setupMustRemindAlarms() {
173	  const all = await chrome.alarms.getAll();
174	  for (const a of all) {
175	    if (a.name.startsWith(MUST_REMIND_PREFIX)) await chrome.alarms.clear(a.name);
176	  }
177	  const cfg = await getConfig();
178	  if (cfg.mustRemindEnabled === false) {
179	    log.info('MustRemind alarms cleared (disabled)');
180	    return;
181	  }
182	  const raw = Array.isArray(cfg.mustRemindTimes) && cfg.mustRemindTimes.length
183	    ? cfg.mustRemindTimes
184	    : DEFAULT_CONFIG.mustRemindTimes;
185	  const seen = {};
186	  for (const t of raw) {
187	    const p = parseHHMM(t);
188	    if (!p || seen[p.label]) continue;
189	    seen[p.label] = true;
190	    const when = nextWhen(p.label);
191	    if (!when) continue;
192	    chrome.alarms.create(MUST_REMIND_PREFIX + p.label, { when });
193	    log.info('MustRemind alarm set: ' + p.label + ' → ' + new Date(when).toLocaleString('zh-CN'));
194	  }
195	}
