197	// ---------------- 商品明细 → 带链接的告警行 ----------------
198	// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
199	function editLink(productId) {
200	  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
201	}
202	// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
203	function itemLines(items, total) {
204	  const lines = [];
205	  if (Array.isArray(items) && items.length) {
206	    for (const it of items) {
207	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
208	      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
209	    }
210	    if (typeof total === 'number' && total > items.length) {
211	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
212	    }
213	  } else if (typeof total === 'number' && total > 0) {
214	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
215	  }
216	  return lines;
217	}
218	
219	// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
220	async function scanWatchViaTab() {
221	  const tab = await getGoodsTab();
222	  if (!tab) return null;
223	  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
224	}
225	
226	// ---------------- 对比 & 告警（按店） ----------------
227	// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
228	// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
229	const alertChains = {};
230	function diffAndAlert(name) {
231	  const prev = alertChains[name] || Promise.resolve();
232	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
233	  alertChains[name] = next;
234	  return next;
235	}
236	
237	async function _diffAndAlert(name) {
238	  const cfg = await getConfig();
239	  if (!cfg.enabled) return;
240	  const stores = await getStores();
241	  const s = stores[name];
242	  if (!s) return;
243	  const latest = s.latest || {};
244	  const snap = s.snapshot || {};
245	  const events = [];
246	
247	  // 在售数量下降：数字告警（被动监测第一时间发现），diffOnSale 在轮巡时带具体商品名+链接点名。
248	  // v3 曾移除此项（担心与 diffOnSale 重复），但 diffOnSale 只在空闲轮巡触发，移除后用户手动刷新/页面
249	  // 自然浏览时下架完全漏报——现在恢复，与 diffOnSale 互补：此处报数字，轮巡补点名。
250	  if (typeof latest.onSale === 'number' && typeof snap.onSale === 'number' && latest.onSale < snap.onSale) {
251	    events.push(`📉 在售数量下降：${snap.onSale} → ${latest.onSale}`);
252	  }
253	  if (typeof latest.trafficWatch === 'number' && typeof snap.trafficWatch === 'number' && latest.trafficWatch > snap.trafficWatch) {
254	    events.push(`⚠️ 商品流量待关注增加：${snap.trafficWatch} → ${latest.trafficWatch}`);
255	    // 被动扫到的 watchItems 往往为空（限流商品散落在其它页）→ 主动点筛选把这几条捞出来，带链接点名。
256	    let items = Array.isArray(latest.watchItems) ? latest.watchItems : [];
257	    let total = latest.trafficWatch;
258	    const scan = await scanWatchViaTab();
259	    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
260	      items = scan.items;
261	      if (typeof scan.total === 'number') total = scan.total;
262	    }
263	    events.push(...itemLines(items, total));
264	  }
265	  // 「商品流量近期有下降」商品数增加（相对已建立的基准，首次不报）
266	  if (typeof latest.trafficDecline === 'number' && typeof snap.trafficDecline === 'number' && latest.trafficDecline > snap.trafficDecline) {
267	    events.push(`🔴 商品流量近期有下降增加：${snap.trafficDecline} → ${latest.trafficDecline}（本页可见）`);
268	    events.push(...itemLines(latest.declineItems, null));
269	  }
270	
271	  if (events.length > 0) {
272	    log.info('Alert triggered: store=' + name + ' eventCount=' + events.length);
273	    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
274	    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
275	    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
276	  }
277	
278	  // 合并式更新该店基准快照（只覆盖本次拿到的数值），幂等只报一次。
279	  // 重新取一次 store：主动扫筛选期间 content 可能又上报过 latest，避免用旧闭包覆盖。
280	  const stores2 = await getStores();
281	  const s2 = stores2[name] || s;
282	  const L2 = s2.latest || latest;
283	  const newSnap = Object.assign({}, s2.snapshot || snap);
284	  if (typeof L2.onSale === 'number') newSnap.onSale = L2.onSale;
285	  if (typeof L2.total === 'number') newSnap.total = L2.total;
286	  if (typeof L2.trafficWatch === 'number') newSnap.trafficWatch = L2.trafficWatch;
287	  if (typeof L2.trafficDecline === 'number') newSnap.trafficDecline = L2.trafficDecline;
288	  newSnap.ts = Date.now();
289	  s2.snapshot = newSnap;
290	  stores2[name] = s2;
291	  await saveStores(stores2);
292	  log.info('Snapshot updated: store=' + name);
293	}
294	
295	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
296	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
297	// scanStore 为扫描瞬间页面实际所在店：与 name 不符 = 切店竞态（这批是别店数据）→ 整轮作废。
298	async function diffOnSale(name, items, onSaleTabCount, scanStore) {
299	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
300	  if (scanStore && scanStore !== name) { log.warn('onSale scan store mismatch: want=' + name + ' got=' + scanStore + '，本轮作废'); return 0; }
301	  const cfg = await getConfig();
302	  const stores = await getStores();
303	  const s = stores[name] || { latest: {}, snapshot: {} };
304	  // 防残缺扫描/筛选污染误判：以"扫描当时在干净视图下读到的「在售中 N」"为权威在售数
305	  // （content.js scanOnSaleList 复位后读的，不会被「商品流量待关注」筛选污染）；
306	  // 读不到才回退 countStatus 的 latest.onSale。扫到的商品数必须恰好等于它：
307	  //   少了 = 没扫全/分页 → 跳过；多了 = 视图污染（全部/未发布/别店商品混入，可能含从未上架商品）→ 跳过。
308	  //   旧版只查"少"不查"多"，曾放过 20 条污染扫描（在售实为 13）写进基准，
309	  //   下一轮干净扫描引爆「下架15个(在售20→13)」假告警。
310	  const known = (typeof onSaleTabCount === 'number' && onSaleTabCount > 0)
311	    ? onSaleTabCount
312	    : (s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null);
313	  if (known != null && items.length < known) { log.warn('onSale scan incomplete: store=' + name + ' scanned=' + items.length + ' known=' + known); return 0; }
314	  if (known != null && items.length > known) { log.warn('onSale scan overflow: store=' + name + ' scanned=' + items.length + ' known=' + known + '，疑似视图污染，本轮作废'); return 0; }
315	  const newMap = {};
316	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
317	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
318	  let delistedCount = 0;
319	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
320	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
321	    delistedCount = delisted.length;
322	    if (delisted.length) {
323	      const added = Object.keys(newMap).filter((pid) => !(pid in prevMap)).length;
324	      log.warn('Delisted items: store=' + name + ' count=' + delisted.length + ' onSale=' + Object.keys(prevMap).length + '→' + items.length + ' added=' + added);
325	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
326	      // 「在售 A → B」的差值 ≠ 下架数（同期可能有新品上架）；补上新增数让账算得平：A - 下架 + 新增 = B
327	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}${added ? `，同期新增上架 ${added} 个` : ''}）:`,
328	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
329	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
330	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
331	    }
332	  } else {
333	    log.info('First onSale baseline: store=' + name + ' items=' + items.length);
334	  }
335	  // 重新取一次 stores 再写：_diffAndAlert 可能在 diffOnSale 处理期间并发更新过 snapshot 的
336	  // 数值字段（onSale/trafficWatch 等），直接用初始读到的 s 会覆盖掉这些更新 → 基准腐败 → "数据后来不准"。
337	  const stores2 = await getStores();
338	  const s2 = stores2[name] || s;
339	  s2.snapshot = Object.assign({}, s2.snapshot || s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
340	  stores2[name] = s2;
341	  await saveStores(stores2);
342	  return delistedCount;
343	}
344	
345	// 解析店铺名：优先用页面读到的店名；读不到则退回配置里手填的，再退回“当前店铺”
346	async function resolveStore(msgStore) {
347	  if (msgStore && String(msgStore).trim()) return String(msgStore).trim();
348	  const cfg = await getConfig();
349	  return (cfg.storeName && cfg.storeName.trim()) || '当前店铺';
350	}
351	
352	// ---------------- 消息处理 ----------------
353	chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
354	  (async () => {
355	    try {
356	    if (msg.type === 'log') {
357	      if (msg.entry && msg.entry.ts && msg.entry.level) {
358	        TemuLogger._writeEntry(msg.entry);
359	      }
360	      sendResponse({ ok: true });
361	      return;
362	    }
363	    if (msg.type === 'capture') {
364	      const name = await resolveStore(msg.store);
365	      log.info('Capture: kind=' + msg.kind + ' store=' + name);
366	      if (msg.kind === 'countStatus') {
367	        const p = parseCountStatus(msg.body);
368	        if (p && p.onSale != null) {
369	          await updateStoreLatest(name, { onSale: p.onSale, unpublished: p.unpublished, removed: p.removed, deleted: p.deleted });
370	          await diffAndAlert(name);
371	        }
372	      } else if (msg.kind === 'pageQuery') {
373	        const p = parsePageQuery(msg.body);
374	        if (p) await updateStoreLatest(name, { total: p.total });
375	      } else if (msg.kind === 'skuSpecList') {
376	        const p = parseSkuSpecList(msg.body);
377	        if (p) {
378	          log.info('skuSpecList captured: store=' + name + ' count=' + p.skuSpecCount);
379	          await updateStoreLatest(name, { skuSpecs: p.skuSpecs, skuSpecCount: p.skuSpecCount });
380	          // 保留原始响应前 2000 字符，便于后续精调解析字段
381	          await chrome.storage.local.set({ lastSkuSpecRaw: msg.body.slice(0, 2000) });
382	        }
383	      } else if (msg.kind === 'skuPriceQuery') {
384	        const p = parseSkuPriceQuery(msg.body);
385	        if (p) {
386	          log.info('skuPriceQuery captured: store=' + name);
387	          await updateStoreLatest(name, { skuPriceRaw: p.skuPriceRaw });
388	        }
389	      }
390	      sendResponse({ ok: true });
391	      return;
392	    }
393	    if (msg.type === 'chipStats') {
394	      const patch = {};
395	      if (typeof msg.trafficWatch === 'number') patch.trafficWatch = msg.trafficWatch;
396	      if (typeof msg.trafficDecline === 'number') patch.trafficDecline = msg.trafficDecline;
397	      if (Array.isArray(msg.watchItems)) patch.watchItems = msg.watchItems;
398	      if (Array.isArray(msg.declineItems)) patch.declineItems = msg.declineItems;
399	      if (Object.keys(patch).length) {
400	        const name = await resolveStore(msg.store);
401	        log.info('ChipStats: store=' + name + ' trafficWatch=' + (msg.trafficWatch != null ? msg.trafficWatch : 'null') + ' trafficDecline=' + (msg.trafficDecline != null ? msg.trafficDecline : 'null'));
402	        await updateStoreLatest(name, patch);
403	        await diffAndAlert(name);
404	      }
405	      sendResponse({ ok: true });
406	      return;
407	    }
408	    if (msg.type === 'getStatus') {
409	      sendResponse({
410	        bgVersion: 'v8-下架扫描防污染',
411	        config: await getConfig(),
412	        stores: await getStores(),
413	        ...(await chrome.storage.local.get(['lastAlert', 'lastCycle', 'lastMustRemind'])),
414	      });
415	      return;
416	    }
417	    if (msg.type === 'addStore') {
418	      const name = (msg.name || '').trim();
419	      log.info('Add store: ' + name);
420	      if (!name) { sendResponse({ ok: false, msg: '店铺名不能为空' }); return; }
421	      const stores = await getStores();
422	      if (stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」已存在' }); return; }
423	      stores[name] = { latest: {}, snapshot: {} };
424	      await saveStores(stores);
425	      sendResponse({ ok: true, msg: '已添加「' + name + '」，下次轮巡将尝试切到该店抓数' });
426	      return;
427	    }
428	    if (msg.type === 'deleteStore') {
429	      const name = (msg.name || '').trim();
430	      log.info('Delete store: ' + name);
431	      const stores = await getStores();
432	      if (!stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」不存在' }); return; }
433	      delete stores[name];
434	      await saveStores(stores);
435	      sendResponse({ ok: true, msg: '已删除「' + name + '」' });
436	      return;
437	    }
438	    if (msg.type === 'checkNow') {
439	      log.info('Manual check requested');
440	      sendResponse(await pollNow());
441	      return;
442	    }
443	    if (msg.type === 'cycleNow') {
444	      log.info('Manual cycle requested');
445	      sendResponse(await cycleStores('manual'));
446	      return;
447	    }
448	    if (msg.type === 'testFeishu') {
449	      log.info('Test Feishu requested');
450	      const cfg = await getConfig();
451	      const r = await sendFeishu(cfg.webhook, '✅ Temu 监测测试', ['这是一条测试消息，收到说明飞书配置正常。', '', `_${new Date().toLocaleString('zh-CN')}_`], 'green');
452	      sendResponse(r);
453	      return;
454	    }
455	    if (msg.type === 'mustRemindNow') {
456	      log.info('Manual mustRemind requested');
457	      sendResponse(await sendMustRemind('手动'));
458	      return;
459	    }
460	    } catch (e) {
461	      log.error('Message handler error: ' + (e && e.message ? e.message : String(e)));
462	      sendResponse({ ok: false, msg: 'Internal error' });
463	    }
464	  })();
465	  return true;
466	});
467	
468	// ---------------- 自动轮巡（切遍每个店抓数，再切回原店；仅空闲时触发） ----------------
469	const IDLE_SECONDS = 240; // 无操作 4 分钟视为空闲
470	let cycling = false;
471	
472	async function getGoodsTab() {
473	  const tabs = await chrome.tabs.query({ url: 'https://agentseller.temu.com/*' });
474	  return tabs.find((t) => /goods\/list/.test(t.url || '')) || tabs[0] || null;
475	}
476	function sendTab(tabId, cmd) {
477	  return new Promise((resolve) => {
478	    try {
479	      chrome.tabs.sendMessage(tabId, cmd, (resp) => {
480	        if (chrome.runtime.lastError) resolve(null); else resolve(resp);
481	      });
482	    } catch (e) { resolve(null); }
483	  });
484	}
485	async function sendTabRetry(tabId, cmd, tries) {
486	  for (let i = 0; i < (tries || 8); i++) {
487	    const r = await sendTab(tabId, cmd);
488	    if (r) return r;
489	    await new Promise((res) => setTimeout(res, 1000)); // 页面重载后 content 未就绪，重试
490	  }
491	  return null;
492	}
493	function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
494	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
495	async function waitForStoreCapture(name, sinceTs, timeout) {
496	  const t0 = Date.now();
497	  while (Date.now() - t0 < (timeout || 25000)) {
498	    const stores = await getStores();
499	    const L = stores[name] && stores[name].latest;
500	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
501	    await sleep(1500);
502	  }
503	  return false;
504	}
505	
506	async function cycleStores(reason) {
507	  if (cycling) return { ok: false, msg: '轮巡进行中' };
508	  cycling = true;
509	  log.info('Cycle started: reason=' + reason);
510	  const cycleLog = [];
511	  try {
512	    const tab = await getGoodsTab();
513	    if (!tab) { log.warn('Cycle: no goods tab found'); return { ok: false, msg: '没有打开的 Temu 商品页' }; }
514	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
515	    const original = cur && cur.store;
516	    cycleLog.push('当前店：' + (original || '未知'));
517	
518	    // 店铺清单：优先用”已知店”（之前逛各店时按顶栏店名记下的，干净准确）；
519	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
520	    const known = Object.keys(await getStores()).filter((n) => n && n !== '当前店铺');
521	    let names;
522	    if (known.length >= 2) {
523	      names = known;
524	      cycleLog.push('店铺(已知)：' + names.join(', '));
525	    } else {
526	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
527	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
528	      cycleLog.push('店铺(探测)：' + names.join(', '));
529	    }
530	    if (names.length === 0) { log.warn('Cycle: no stores identified'); return { ok: false, msg: '没识别到店铺清单' }; }
531	    log.info('Cycle stores: ' + names.length + ' stores: ' + names.join(', '));
532	
533	    for (const name of names) {
534	      if (name === original) continue; // 原店最后再确认；先切别的
535	      const since = Date.now();
536	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
537	      if (!r || !r.ok) { log.warn('Cycle switch FAILED: store=' + name); cycleLog.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
538	      const got = await waitForStoreCapture(name, since, 25000);
539	      cycleLog.push((got ? '✓ ' : '✗ ') + name);
540	      if (got) {
541	        log.info('Cycle captured: store=' + name);
542	      } else {
543	        log.warn('Cycle capture TIMEOUT: store=' + name);
544	      }
545	      // 扫在售清单 → diff 出下架商品（带链接告警）；os.store 用于校验扫描时页面确实在目标店
546	      if (got) {
547	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
548	        if (os && os.msg) log.warn('scanOnSale aborted: store=' + name + ' ' + os.msg);
549	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items, os.onSaleTabCount, os.store); if (d) { log.warn('Cycle delisted: store=' + name + ' count=' + d); cycleLog.push('  ↳下架' + d + '个'); } }
550	      }
551	    }
552	    // 切回原店
553	    if (original) {
554	      const since = Date.now();
555	      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
556	      const gotBack = await waitForStoreCapture(original, since, 25000);
557	      if (gotBack) {
558	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
559	        if (os && os.msg) log.warn('scanOnSale aborted: store=' + original + ' ' + os.msg);
560	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items, os.onSaleTabCount, os.store); if (d) cycleLog.push('  ↳' + original + '下架' + d + '个'); }
561	      }
562	      cycleLog.push('已切回 ' + original);
563	    }
564	    const summary = cycleLog.join(' | ');
565	    log.info('Cycle completed: ' + summary);
566	    await chrome.storage.local.set({ lastCycle: { ts: Date.now(), reason, summary } });
567	    return { ok: true, msg: summary };
568	  } catch (e) {
569	    log.error('Cycle error: ' + (e && e.message ? e.message : String(e)));
570	    throw e;
571	  } finally { cycling = false; }
572	}
573	
574	async function pollNow() {
575	  log.info('Poll: reloading goods list page');
576	  const tab = await getGoodsTab();
577	  if (!tab) { log.warn('Poll: no goods tab found'); return { ok: false, msg: '未找到打开的 Temu 后台标签页，请先登录并打开商品列表页' }; }
578	  if (/goods\/list/.test(tab.url || '')) { await chrome.tabs.reload(tab.id, { bypassCache: false }); return { ok: true, msg: '已刷新后台商品页' }; }
579	  await chrome.tabs.update(tab.id, { url: GOODS_URL });
580	  return { ok: true, msg: '已导航到商品列表页' };
581	}
582	
583	// 定时：空闲则轮巡所有店，否则不打扰（靠随看随记覆盖当前店）
584	// 必提醒：每天固定时刻强制发状态汇报（无异常也发）
585	chrome.alarms.onAlarm.addListener((a) => {
586	  log.info('Alarm fired: ' + a.name);
587	  if (a.name === 'poll') {
588	    chrome.idle.queryState(IDLE_SECONDS, (state) => {
589	      if (state === 'idle' || state === 'locked') {
590	        log.info('System idle, starting automatic cycle');
591	        cycleStores('idle');
592	      } else {
593	        log.info('System active, skipping automatic cycle');
594	      }
595	    });
596	    return;
597	  }
598	  if (a.name.startsWith(MUST_REMIND_PREFIX)) {
599	    const slot = a.name.slice(MUST_REMIND_PREFIX.length);
600	    // chrome.alarms 的 when 是一次性的 → 发完立刻重排下一天同一时刻
601	    (async () => {
602	      try {
603	        await sendMustRemind(slot);
604	      } catch (e) {
605	        log.error('MustRemind error: ' + (e && e.message ? e.message : String(e)));
606	      } finally {
607	        await setupMustRemindAlarms();
608	      }
609	    })();
610	  }
611	});
612	
613	async function setupAlarm() {
614	  await chrome.storage.local.remove('trafficSample'); // 清早期诊断残留
615	  const cfg = await getConfig();
616	  await chrome.alarms.clear('poll');
617	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
618	  log.info('Alarm set: every ' + cfg.intervalMinutes + 'min, enabled=' + cfg.enabled);
619	  await setupMustRemindAlarms();
620	}
621	chrome.runtime.onInstalled.addListener(() => { log.info('Extension installed/updated, setting up alarm'); setupAlarm(); });
622	chrome.runtime.onStartup.addListener(() => { log.info('Chrome startup, setting up alarm'); setupAlarm(); });
623	chrome.storage.onChanged.addListener((changes, area) => { if (area === 'local' && changes.config) { log.info('Config changed, reconfiguring alarm'); setupAlarm(); } });
624	
625	log.info('Service worker started');
626	// SW 被唤醒时（非 install/startup）也补一次闹钟，避免长时间休眠后漏排
627	setupAlarm();
