1	// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
2	// ④ 接收后台指令自动切店(轮巡用)。
3	(function () {
4	  var LOG = TemuLogger.createLogger('content');
5	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
6	  LOG.info('content.js loaded -- v7');
7	
8	  // 页面操作互斥锁：scanWatchList/scanOnSaleList/switchTo 都会改动「快速筛选/tab/切店」状态，
9	  // 绝不能并发——否则「商品流量待关注」筛选一打开，并发的在售扫描就只扫到筛选后的几条，
10	  // 误判成「下架 N 个」（这是历史假告警「在售 13→3」的根因）。所有改动型指令排队串行执行。
11	  let opChain = Promise.resolve();
12	  function withLock(fn) {
13	    const run = opChain.then(fn, fn); // 无论上一个成功/失败都接着跑（fn 不依赖上个结果）
14	    opChain = run.then(() => {}, (e) => { LOG.warn('Locked operation failed: ' + (e && e.message || e)); }); // 吞掉结果/异常，保持链条连续
15	    return run; // 调用方拿到 fn 的真实结果/异常
16	  }
17	
18	  // 注入 MAIN world hook
19	  try {
20	    const s = document.createElement('script');
21	    s.src = chrome.runtime.getURL('inject.js');
22	    s.onload = () => s.remove();
23	    (document.head || document.documentElement).appendChild(s);
24	    LOG.info('inject.js injected into MAIN world');
25	  } catch (e) { LOG.warn('inject.js injection failed: ' + (e && e.message || e)); }
26	
27	  // ---------- 读当前店铺名（右上角英文店名） ----------
28	  function findStoreNameEl() {
29	    const W = window.innerWidth;
30	    let best = null;
31	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
32	      const t = (el.textContent || '').trim();
33	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
34	      if (t.length < 2 || t.length > 30) continue;
35	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
36	      // 排除纯大写+数字的货号/SKU（如 JMCATSZJ4）——真实店名都含小写字母
37	      if (/^[A-Z0-9]+$/.test(t)) continue;
38	      if (el.children.length > 2) continue;
39	      const r = el.getBoundingClientRect();
40	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
41	      if (r.left < W * 0.5) continue;
42	      if (!best || r.left > best.left) best = { el, left: r.left };
43	    }
44	    return best ? best.el : null;
45	  }
46	  function readStoreName() { const el = findStoreNameEl(); return el ? (el.textContent || '').trim() : null; }
47	
48	  // ---------- 转发接口响应 ----------
49	  window.addEventListener('message', (e) => {
50	    if (e.source !== window) return;
51	    const d = e.data;
52	    if (!d || d.__temuMon !== true) return;
53	    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
54	  });
55	
56	  // ---------- 读流量异常 ----------
57	  // ①「商品流量待关注」是常驻的快速筛选 chip，实测 DOM（勿凭空改）：
58	  //     <div class="use-quick-field_tsx_card__HASH"><span>商品流量待关注</span>
59	  //       <span class="use-quick-field_tsx_countDistance__HASH">4</span></div>
60	  //   计数在独立的 countDistance span 里（chip 常驻，N=0 也在，只有 N 变大才是真异常）。
61	  // ②「商品流量近期有下降」不是 chip，是逐行红色徽标（见 countDeclineBadges）。
62	  // 关键坑：行内徽标「商品流量待关注 ›」嵌在价格 TD 里 → 价格单元格文本也含该标签。
63	  //   旧的"全页捞文本+最短优先"靠排序巧合才没读到价格数字；这里改为直接锚定 chip 容器。
64	  function readChipCount(all, label) {
65	    const re = new RegExp(label);
66	    // 精确路径：定位快速筛选 chip 容器（class 前缀 use-quick-field_tsx_card__ 稳定，
67	    // hash 后缀随构建变，用 *= 匹配前缀；card__ 带双下划线以免误匹配 cardBlock__）。
68	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
69	      if (!re.test(card.textContent || '')) continue;
70	      const cnt = card.querySelector('[class*="countDistance"]');
71	      if (cnt && /\d/.test(cnt.textContent || '')) {
72	        return Number((cnt.textContent || '').replace(/[^\d]/g, ''));
73	      }
74	      const m = (card.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
75	      if (m) return Number(m[1].replace(/,/g, ''));
76	    }
77	    // 兜底：chip class 若被改名，退回旧的全页文本匹配（最短优先 + 就近数字）
78	    const labels = all
79	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
80	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
81	    for (const el of labels) {
82	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
83	        if (!cand) continue;
84	        const m = (cand.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
85	        if (m) return Number(m[1].replace(/,/g, ''));
86	      }
87	      let sib = el.nextElementSibling;
88	      for (let i = 0; i < 3 && sib; i++, sib = sib.nextElementSibling) {
89	        const st = (sib.textContent || '').trim();
90	        if (/^[\d,]+$/.test(st)) return Number(st.replace(/,/g, ''));
91	      }
92	    }
93	    return null; // 读不到 → 未知（不当作 0，也不当作"有"）
94	  }
95	  // 「商品流量近期有下降」不是带计数的筛选 chip，而是逐行的红色徽标（列「商品优化事项」下）。
96	  // 因此按"当前页可见的行内徽标个数"来统计。注意：只覆盖当前页（默认 20 条/页），
97	  // 下降商品若在其它页则数不到——被动读数的固有限制，要精确总数得点筛选（主动模式）。
98	  function countDeclineBadges(all) {
99	    let n = 0;
100	    for (const e of all) {
101	      const t = (e.textContent || '').trim();
102	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
103	      // 只数最内层节点，避免父容器重复计数
104	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
105	      const r = e.getBoundingClientRect();
106	      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
107	    }
108	    return n;
109	  }
110	  // 扫描当前页商品行：按「SPU ID(=productId)」边界把行分组成商品，
111	  // 识别哪些商品带「商品流量待关注 / 商品流量近期有下降」徽标，取 productId + 商品名 + SKC。
112	  // 局限：只覆盖当前页(默认 20 条/页)，跨页的限流/下降商品扫不到——被动读的固有限制
113	  //（chip 计数 trafficWatch 才是全量总数；这里只为「点名 + 给编辑链接」）。
114	  function scanProducts() {
115	    const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
116	    const products = [];
117	    let cur = null;
118	    for (const tr of rows) {
119	      const t = tr.textContent || '';
120	      const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/); // DOM「SPU ID」= API/编辑页的 productId
121	      if (spu) {
122	        // 商品名只在「商品信息」那一格取（含 SPU ID 的 td），排除「标签：值」属性行，取最长一段。
123	        // （曾扫整行 → 第 3 条抓成隔壁「商品属性」列的「主体材质：铝合金」，故限定到该 td。）
124	        const infoTd = [...tr.querySelectorAll('td')].find((td) => /SPU\s*ID/.test(td.textContent || '')) || tr;
125	        const name = [...infoTd.querySelectorAll('*')].map((e) => (e.textContent || '').trim())
126	          .filter((x) => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
127	          .sort((a, b) => b.length - a.length)[0] || '';
128	        cur = { productId: spu[1], skc: (t.match(/SKC\s*ID[:：]\s*(\d+)/) || [])[1] || '', name: name, watch: false, decline: false };
129	        products.push(cur);
130	      }
131	      if (cur) {
132	        if (/商品流量待关注/.test(t)) cur.watch = true;
133	        if (/商品流量近期有下降/.test(t)) cur.decline = true;
134	      }
135	    }
136	    return products;
137	  }
138	  function readTraffic() {
139	    const all = [...document.querySelectorAll('*')];
140	    return {
141	      watch: readChipCount(all, '商品流量待关注'),
142	      decline: countDeclineBadges(all),
143	    };
144	  }
145	  const pickItem = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
146	  // 常驻轮询：每 2s 读一次 chip 计数 + 扫一次商品明细，但**只在结果变化时上报**
147	  //（靠 dedupe 避免刷爆后台）。这样用户后点「商品流量待关注」筛选/翻页时，
148	  // 明细也会在 2s 内自动刷新——旧版只在加载后 40s 内扫、之后点筛选就不扫了。
149	  let tries = 0;
150	  let lastKey = '';
151	  setInterval(() => {
152	    tries++;
153	    // 商品表格是否已渲染出行——徽标在行里，必须等行出来再扫，否则会在徽标出现前就读成空
154	    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
155	    const { watch, decline } = readTraffic();
156	    const msg = { type: 'chipStats', store: readStoreName() };
157	    if (watch != null) msg.trafficWatch = watch;
158	    let watchItems = [];
159	    let declineItems = [];
160	    if (gridReady) {
161	      const products = scanProducts();
162	      watchItems = products.filter((p) => p.watch).map(pickItem);
163	      declineItems = products.filter((p) => p.decline).map(pickItem);
164	      msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
165	      msg.watchItems = watchItems;
166	      msg.declineItems = declineItems;
167	    }
168	    // 有 count 时等网格就绪再发（尽量带上明细）；网格长时间卡「加载中」(tries>8≈16s)时 count-only 兜底
169	    const readyOrTimedOut = gridReady || tries > 8;
170	    if (!((msg.trafficWatch != null && readyOrTimedOut) || 'trafficDecline' in msg)) return;
171	    // 结果没变化就不重发；变化了（如刚点了筛选、切了店）才上报
172	    const key = JSON.stringify([msg.store, msg.trafficWatch, msg.trafficDecline,
173	      watchItems.map((i) => i.productId), declineItems.map((i) => i.productId)]);
174	    if (key === lastKey) return;
175	    lastKey = key;
176	    LOG.info('Traffic update: watch=' + (watch != null ? watch : 'null') + ' decline=' + (decline != null ? decline : 'null') + ' watchItems=' + watchItems.length + ' declineItems=' + declineItems.length);
177	    try { chrome.runtime.sendMessage(msg); } catch (e) {}
178	  }, 2000);
179	
180	  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
181	  async function waitFor(fn, timeout, step) {
182	    const t0 = Date.now();
183	    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
184	  }
185	  function textEls(re, maxLen) {
186	    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
187	  }
188	  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
189	  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
190	  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
191	  function realClick(el) {
192	    if (!el) return false;
193	    const opts = { bubbles: true, cancelable: true, view: window };
194	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
195	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
196	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
197	    }
198	    try { el.click(); } catch (e) {}
199	    return true;
200	  }
201	  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
202	  function closeModal() {
203	    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
204	    if (x) { realClick(x); return; }
205	    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
206	  }
207	
208	  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
209	  function domSkel(el, maxLen) {
210	    if (!el) return 'null';
211	    let h = (el.outerHTML || '');
212	    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
213	    return h.slice(0, maxLen || 2200);
214	  }
215	
216	  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }
217	
218	  async function openStoreModal(diag) {
219	    diag = diag || [];
220	    if (modalOpen()) { diag.push('弹窗已开'); return true; }
221	    const nameEl = findStoreNameEl();
222	    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
223	    if (nameEl) {
224	      // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
225	      const r = nameEl.getBoundingClientRect();
226	      realClick(clickableAncestor(nameEl));
227	      const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
228	      if (el && el !== nameEl) realClick(el);
229	    }
230	    // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
231	    const sw = await waitFor(() => {
232	      const cands = textEls(/^切换$/, 6).filter(visible);
233	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
234	    }, 3500);
235	    diag.push('下拉切换按钮=' + !!sw);
236	    if (sw) realClick(sw);
237	    const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
238	    diag.push('弹窗打开=' + ok);
239	    if (!ok) {
240	      LOG.warn('Open store modal failed: ' + diag.join(' ; '));
241	      const cands = textEls(/切换/, 8).map((e) => {
242	        const b = e.getBoundingClientRect();
243	        return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
244	      });
245	      diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
246	      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
247	    }
248	    return ok;
249	  }
250	
251	  async function listStores() {
252	    if (!(await openStoreModal())) return [];
253	    await sleep(500);
254	    // 每个店铺行都带”半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文。
255	    // 额外检查：审核中/已禁用的店铺（如 FashionNest 显示 “application is under review”）
256	    // 没有可用的「切换」按钮，通过判断按钮是否 disabled/aria-disabled 来过滤。
257	    const tags = textEls(/托管/, 6).filter(visible);
258	    const names = [];
259	    for (const tag of tags) {
260	      let row = tag.parentElement;
261	      for (let i = 0; i < 4 && row; i++) {
262	        const en = [...row.querySelectorAll('span,div,p,a')]
263	          .map((e) => (e.textContent || '').trim())
264	          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
265	        if (en) {
266	          // 确认该店铺行有可用的「切换」按钮（过滤审核中/已禁用的店）
267	          let container = row;
268	          for (let j = 0; j < 5 && container; j++) {
269	            const switchBtn = [...container.querySelectorAll('button,[role=button]')]
270	              .find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
271	            if (switchBtn) { names.push(en); break; }
272	            container = container.parentElement;
273	          }
274	          break;
275	        }
276	        row = row.parentElement;
277	      }
278	    }
279	    closeModal();
280	    const uniq = [...new Set(names)];
281	    LOG.info('listStores: ' + uniq.length + ' stores: ' + uniq.join(', '));
282	    return uniq;
283	  }
284	
285	  async function switchTo(target) {
286	    const diag = [];
287	    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
288	    await sleep(300);
289	    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
290	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
291	    const row = innermost(rows);
292	    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
293	    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
294	    if (!btn) {
295	      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
296	      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
297	    }
298	    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
299	    LOG.info('Switching store to: ' + target);
300	    realClick(btn); // 触发切店（SPA 更新或整页重载）
301	    return { ok: true, msg: '已点击切换到 ' + target };
302	  }
303	
304	  // ---------- 主动捞「商品流量待关注」明细（发现异常时调，点筛选→扫→重置） ----------
305	  // 读列表底部「共有 N 条」（筛选生效后该数=待关注总数）
306	  function readTotalCount() {
307	    const el = [...document.querySelectorAll('*')].find(
308	      (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
309	    );
310	    if (!el) return null;
311	    const m = (el.textContent || '').match(/共有\s*([\d,]+)\s*条/);
312	    return m ? Number(m[1].replace(/,/g, '')) : null;
313	  }
314	  // 定位「商品流量待关注」快速筛选 chip 容器（与 readChipCount 同一稳定 class 前缀）
315	  function findWatchChip() {
316	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
317	      if (/商品流量待关注/.test(card.textContent || '')) return card;
318	    }
319	    return null;
320	  }
321	  // 点「重置」清掉快速筛选，恢复用户视图
322	  function clickReset() {
323	    const btn = textEls(/^重置$/, 6).filter(visible)[0];
324	    if (btn) realClick(clickableAncestor(btn));
325	  }
326	  // 点开「商品流量待关注」筛选 → 扫出这几条商品(productId+name+skc) → 重置。
327	  // 筛选生效后网格里每行都是待关注商品，故取全部行（不再依赖行内徽标）。
328	  // 只覆盖筛选后的当前页(默认 20 条)，>20 条的溢出由 total 提示行说明。
329	  async function scanWatchList() {
330	    LOG.info('scanWatchList: scanning...');
331	    const chip = findWatchChip();
332	    if (!chip) { LOG.warn('scanWatchList: chip not found'); return { store: readStoreName(), items: [], applied: false, msg: '未找到待关注筛选 chip' }; }
333	    const before = readTotalCount();
334	    realClick(clickableAncestor(chip));
335	    // 等列表真正刷新：底部「共有 N 条」的数值发生变化（通常变小）才算筛选生效
336	    await waitFor(() => {
337	      const t = readTotalCount();
338	      return (t != null && before != null && t !== before) ? t : null;
339	    }, 8000, 300);
340	    await sleep(1200); // 等筛选后的网格稳定渲染
341	    const after = readTotalCount();
342	    // 仅当确实生效（数值变化且不大于原总数）才采纳，绝不把未筛选的整页当成待关注
343	    const applied = after != null && before != null && after !== before && after <= before;
344	    let items = [];
345	    if (applied) items = scanProducts().map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
346	    // 复位（必须彻底清掉筛选，否则会污染随后的在售扫描 → 误报下架）：
347	    //   ① 若已生效，再点一次同一 chip toggle 回未选中（比只点「重置」更精准可靠）；
348	    //   ② 再点「重置」兜底；③ 等「共有 N 条」回升到筛选前的值，确认筛选真的清掉了。
349	    if (applied) realClick(clickableAncestor(chip));
350	    clickReset();
351	    await waitFor(() => {
352	      const t = readTotalCount();
353	      return (t != null && before != null && t >= before) ? t : null;
354	    }, 6000, 300);
355	    await sleep(600);
356	    LOG.info('scanWatchList done: applied=' + applied + ' items=' + items.length + ' total=' + after);
357	    return { store: readStoreName(), items: items, total: after, applied: applied };
358	  }
359	
360	  // 读某个 tab 标签上印的数字（形如「在售中 13」/「全部 214」）。干净无筛选视图下=真实数量。
361	  function readTabCount(re) {
362	    const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
363	    for (const el of labels) {
364	      const t = (el.textContent || '').trim();
365	      if (re.test(t)) { const m = t.match(/(\d[\d,]*)/); if (m) return Number(m[1].replace(/,/g, '')); }
366	    }
367	    return null;
368	  }
369	  // 扫「在售中」商品清单：先复位到干净视图 → 点在售 tab → 确认视图生效 → scanProducts 取 productId+name+skc。
370	  // 用于 background diff 出"上轮在售、这轮不在"的下架商品。仅轮巡(空闲)时调，扫完点回「全部」。
371	  // ⚠️ 关键①：扫描前**必须**清掉一切快速筛选（尤其「商品流量待关注」）——否则会只扫到筛选后的
372	  //    几条在售商品，误报「下架 N 个」（历史假告警根因）。这里主动复位，不依赖调用时机的干净。
373	  // ⚠️ 关键②：点完「在售中」必须验证视图真的生效（底部「共有 N 条」== tab 上「在售中 N」）再扫。
374	  //    点击可能被切店残留弹窗/背挡拦截，点了 ≠ 生效；若在「全部」「未发布」视图下扫，
375	  //    会混入从未上架的商品写进基准（污染扫描只增不减、当时不告警，悄悄脏掉基准，
376	  //    下一轮干净扫描才引爆「下架15个(在售20→13)」式假告警）。验证不过就放弃本轮——宁可漏一轮，不脏基准。
377	  async function scanOnSaleList() {
378	    LOG.info('scanOnSaleList: scanning...');
379	    const findTab = (re) => {
380	      const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
381	      return labels.find((e) => re.test((e.textContent || '').trim())) || textEls(re, 14).filter(visible)[0] || null;
382	    };
383	    const backToAll = () => { const t = findTab(/^全部/); if (t) realClick(clickableAncestor(t)); };
384	    // ① 复位到干净、无快速筛选的状态：先回「全部」tab，再点「重置」清掉任何快速筛选 chip。
385	    backToAll();
386	    await sleep(300);
387	    clickReset();
388	    await sleep(1000);
389	    // ② 点「在售中」tab 并等视图生效（底部总数 == 在售 tab 计数）；点击可能被残留弹窗拦截 → 失败重试一次
390	    let tabCount = null;
391	    let viewOk = false;
392	    for (let attempt = 1; attempt <= 2 && !viewOk; attempt++) {
393	      const onSaleTab = findTab(/^在售中/);
394	      if (onSaleTab) realClick(clickableAncestor(onSaleTab));
395	      await waitFor(() => document.querySelector('[data-testid="beast-core-table-body-tr"]'), 8000, 300);
396	      await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
397	      tabCount = readTabCount(/^在售中/);
398	      if (tabCount == null) { viewOk = true; break; } // 读不到 tab 数 → 无法交叉验证，放行（后台仍有数量上限兜底）
399	      const ok = await waitFor(() => { const t = readTotalCount(); return (t != null && t === tabCount) ? true : null; }, 6000, 300);
400	      if (ok || readTotalCount() == null) { viewOk = true; break; } // 生效；footer 读不到 → 放行
401	      LOG.warn('scanOnSaleList: 在售视图未生效(第' + attempt + '次) gridTotal=' + readTotalCount() + ' tabCount=' + tabCount);
402	      clickReset();
403	      await sleep(800);
404	    }
405	    if (!viewOk) {
406	      LOG.warn('scanOnSaleList aborted: 在售视图两次都未生效，本轮放弃（不动基准）');
407	      backToAll();
408	      return { store: readStoreName(), items: [], onSaleTabCount: tabCount, msg: '在售视图未生效，本轮放弃扫描' };
409	    }
410	    // ③ 读干净视图下「在售中 N」的真实数字——作为 background 判定"是否扫全/是否被筛选污染"的权威值
411	    const onSaleTabCount = readTabCount(/^在售中/);
412	    const products = scanProducts();
413	    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
414	    // ④ 扫到的行数比「在售中 N」还多 = 视图污染（全部/未发布/别店商品混入）→ 放弃，绝不让它进基准
415	    if (onSaleTabCount != null && items.length > onSaleTabCount) {
416	      LOG.warn('scanOnSaleList aborted: scanned=' + items.length + ' > tabCount=' + onSaleTabCount + '（视图污染，本轮放弃）');
417	      backToAll();
418	      return { store: readStoreName(), items: [], onSaleTabCount: onSaleTabCount, msg: '扫描行数超过在售数，疑似视图污染，本轮放弃' };
419	    }
420	    var scanMsg = 'scanOnSale: tabCount=' + onSaleTabCount + ' scanned=' + items.length;
421	    if (items.length && onSaleTabCount && items.length < onSaleTabCount) scanMsg += ' (WARNING: possible page truncation)';
422	    LOG.info(scanMsg);
423	    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
424	    backToAll();
425	    LOG.info('scanOnSaleList done: items=' + items.length + ' onSaleTabCount=' + onSaleTabCount);
426	    return { store: readStoreName(), items: items, onSaleTabCount: onSaleTabCount };
427	  }
428	
429	  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
430	    if (!msg || !msg.cmd) return;
431	    (async () => {
432	      try {
433	        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; } // 只读，不入锁
434	        if (msg.cmd === 'listStores') { sendResponse({ names: await withLock(listStores) }); return; }
435	        if (msg.cmd === 'switchTo') { sendResponse(await withLock(() => switchTo(msg.target))); return; }
436	        if (msg.cmd === 'scanOnSale') { sendResponse(await withLock(scanOnSaleList)); return; }
437	        if (msg.cmd === 'scanWatchList') { sendResponse(await withLock(scanWatchList)); return; }
438	      } catch (e) { LOG.error('Command handler error: cmd=' + msg.cmd + ' error=' + String((e && e.message) || e)); sendResponse({ ok: false, msg: String((e && e.message) || e) }); }
439	    })();
440	    return true;
441	  });
442	})();
