For the alarm, I'll use a separate alarm name 'frontPoll' with a configurable period. The user can set it in options (default 3 hours = 180 minutes).

For the cycle function, the approach:
```javascript
async function cycleFrontProducts(reason) {
  const cfg = await getConfig();
  if (!cfg.enabled || cfg.frontCheckEnabled === false) return;

  const productUrls = cfg.productUrls || {};
  const allUrls = [];
  for (const [store, urls] of Object.entries(productUrls)) {
    for (const url of urls) {
      allUrls.push({ store, url });
    }
  }
  if (!allUrls.length) return;

  log.info('FrontCycle started: reason=' + reason + ' urls=' + allUrls.length);

  for (const { store, url } of allUrls) {
    // Check if tab already open for this URL
    let tab = null;
    try {
      const tabs = await chrome.tabs.query({ url: 'https://www.temu.com/*' });
      tab = tabs.find(t => (t.url || '').split('?')[0] === url) || null;
    } catch(e) {}

    if (tab) {
      await sendTabRetry(tab.id, { cmd: 'frontCheck' }, 3);
      await sleep(5000); // wait for parsing
    } else {
      try {
        const newTab = await chrome.tabs.create({ url, active: false });
        await sleep(10000); // wait for SPA render + content script
        try { await chrome.tabs.remove(newTab.id); } catch(e) {}
      } catch(e) {
        log.warn('FrontCycle: failed to open tab for ' + url);
      }
    }
  }

  log.info('FrontCycle completed');
  await chrome.storage.local.set({ lastFrontCycle: { ts: Date.now(), reason } });
}
